export function frameMetrics(image,previous=null){const {width:w,height:h,data}=image;let sum=0,sum2=0,lapSum=0,lap2=0,motion=0,n=0,lapN=0;const gray=i=>data[i*4]*.299+data[i*4+1]*.587+data[i*4+2]*.114,sample=[];for(let y=2;y<h-2;y+=4)for(let x=2;x<w-2;x+=4){const i=y*w+x,v=gray(i);sum+=v;sum2+=v*v;const lap=gray(i-1)+gray(i+1)+gray(i-w)+gray(i+w)-4*v;lapSum+=lap;lap2+=lap*lap;lapN++;sample.push(v);if(previous?.length===Math.ceil((w-4)/4)*Math.ceil((h-4)/4))motion+=Math.abs(v-previous[n]);n++;}return {brightness:sum/(n||1),contrast:Math.sqrt(Math.max(0,sum2/(n||1)-(sum/(n||1))**2)),sharpness:lap2/(lapN||1)-(lapSum/(lapN||1))**2,motion:previous?.length===sample.length?motion/(n||1):0,sample};}
export function cameraError(error){switch(error?.name){case 'NotAllowedError':case 'SecurityError':return 'Camera access blocked. Allow camera access in your browser’s site settings, then start again.';case 'NotFoundError':return 'No camera found. Connect a webcam or enable your phone as a connected camera, then refresh the list.';case 'NotReadableError':case 'AbortError':return 'Camera is unavailable. Close other apps using it, check the phone connection, then retry.';case 'OverconstrainedError':return 'This camera cannot use those settings. Choose another camera or a lower resolution.';case 'CancelledError':return '';default:return error?.message||'Camera could not start. You can still upload a photo.';}}
export class CameraSource{
 constructor(media=globalThis.navigator?.mediaDevices){this.media=media;this.stream=null;this.revision=0;this.onended=null;}
 async devices(){return this.media?.enumerateDevices? (await this.media.enumerateDevices()).filter(d=>d.kind==='videoinput'):[];}
 async start({deviceId='',width=1920}={}){if(!this.media?.getUserMedia)throw Error('Live camera needs HTTPS and a browser with camera support. Use Upload photo instead.');this.stop();const revision=this.revision;let stream;try{stream=await this.media.getUserMedia({audio:false,video:{...(deviceId?{deviceId:{exact:deviceId}}:{facingMode:{ideal:'environment'}}),width:{ideal:width},height:{ideal:Math.round(width*3/4)},frameRate:{ideal:24,max:30}}});}catch(e){if(revision!==this.revision)throw Object.assign(Error('Cancelled'),{name:'CancelledError'});throw e;}if(revision!==this.revision){for(const t of stream.getTracks())t.stop();throw Object.assign(Error('Cancelled'),{name:'CancelledError'});}this.stream=stream;const track=stream.getVideoTracks()[0];track.addEventListener('ended',()=>{if(this.stream===stream){this.stop();this.onended?.();}},{once:true});return stream;}
 stop(){this.revision++;if(this.stream){const stream=this.stream;this.stream=null;for(const track of stream.getTracks())track.stop();}}
 settings(){return this.stream?.getVideoTracks()[0]?.getSettings?.()||{};}
 capabilities(){return this.stream?.getVideoTracks()[0]?.getCapabilities?.()||{};}
 async constraint(key,value){const track=this.stream?.getVideoTracks()[0];if(!track?.applyConstraints)return;await track.applyConstraints({advanced:[{[key]:value}]});}
}
export function grabFrame(video,maxSize=3200){if(video.readyState<2||!video.videoWidth||!video.videoHeight)throw Error('Waiting for a camera frame.');const scale=Math.min(1,maxSize/Math.max(video.videoWidth,video.videoHeight)),canvas=document.createElement('canvas');canvas.width=Math.round(video.videoWidth*scale);canvas.height=Math.round(video.videoHeight*scale);const ctx=canvas.getContext('2d',{willReadFrequently:true});ctx.drawImage(video,0,0,canvas.width,canvas.height);return ctx.getImageData(0,0,canvas.width,canvas.height);}
